"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";

/* ─────────────────────────────────────────────────────────
 * SCROLL STORY: a how-it-works that tells itself as you scroll
 *
 *   steps     the words scroll past a picture that stays put; the
 *             step crossing the middle of the view lights up and
 *             the others wait at a third of their strength
 *   rail      a thin line down the steps fills with the scroll,
 *             continuously, and each step's dot fills as the line
 *             reaches it
 *   picture   one card that reshapes to each step's picture: its
 *             size eases from one to the next while the old
 *             picture blurs out and the new one rises in (and
 *             plays whatever it plays when it arrives). "02 / 04"
 *             rolls above it
 *   narrow    the picture sticks to the top and the steps slide
 *             underneath it
 *   jump      tapping a step scrolls it to the middle
 *
 * Works with the page's scroll or inside any scrolling box.
 * ───────────────────────────────────────────────────────── */

export interface ScrollStoryStep {
  title: string;
  body?: React.ReactNode;
  /** Mounted when its step arrives, so any animation in it plays then. */
  visual: React.ReactNode;
}

export interface ScrollStoryProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "children"
> {
  steps: ScrollStoryStep[];
  /** Where the picture sits when there's room for two columns. */
  side?: "start" | "end";
  onStepChange?: (index: number) => void;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const WIDE = 520;

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** The nearest box that scrolls vertically, or null for the page. */
function scrollParent(el: HTMLElement | null) {
  for (
    let p = el?.parentElement;
    p && p !== document.body;
    p = p.parentElement
  ) {
    if (/(auto|scroll)/.test(getComputedStyle(p).overflowY)) return p;
  }
  return null;
}

/** The card that changes shape between pictures. */
function Stage({
  index,
  children,
  reduced,
}: {
  index: number;
  children: React.ReactNode;
  reduced: boolean;
}) {
  const innerRef = React.useRef<HTMLDivElement>(null);
  const [size, setSize] = React.useState<{ w: number; h: number } | null>(null);
  const [ghost, setGhost] = React.useState<{
    key: number;
    node: React.ReactNode;
  } | null>(null);
  const last = React.useRef({ index, node: children });

  React.useLayoutEffect(() => {
    const el = innerRef.current;
    if (!el) return;
    const measure = () => setSize({ w: el.offsetWidth, h: el.offsetHeight });
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, [index]);

  // A new picture: keep the old one a moment to blur out underneath, raise the new one.
  React.useLayoutEffect(() => {
    if (index === last.current.index) {
      last.current.node = children;
      return;
    }
    if (!reduced)
      setGhost({ key: last.current.index, node: last.current.node });
    last.current = { index, node: children };
    if (reduced) return;
    innerRef.current?.animate(
      [
        {
          opacity: 0,
          transform: "translateY(10px) scale(0.98)",
          filter: "blur(4px)",
        },
        { opacity: 1, transform: "none", filter: "blur(0px)" },
      ],
      { duration: 420, delay: 90, easing: EASE, fill: "backwards" },
    );
  }, [index, children, reduced]);

  return (
    <div
      className="relative overflow-hidden rounded-[20px] border border-border bg-card"
      style={{
        width: size?.w,
        height: size?.h,
        transition:
          reduced || !size
            ? "none"
            : `width 460ms ${EASE}, height 460ms ${EASE}`,
      }}
    >
      {ghost && (
        <div
          key={`ghost-${ghost.key}`}
          aria-hidden="true"
          className="pointer-events-none absolute left-0 top-0 w-max"
          ref={(el) => {
            if (!el || el.dataset.out) return;
            el.dataset.out = "1";
            const a = el.animate(
              [
                { opacity: 1, filter: "blur(0px)", transform: "none" },
                { opacity: 0, filter: "blur(4px)", transform: "scale(0.97)" },
              ],
              { duration: 240, easing: EASE, fill: "forwards" },
            );
            a.onfinish = () =>
              setGhost((g) => (g?.key === ghost.key ? null : g));
          }}
        >
          {ghost.node}
        </div>
      )}
      <div key={index} ref={innerRef} className="w-max">
        {children}
      </div>
    </div>
  );
}

export function ScrollStory({
  steps,
  side = "end",
  onStepChange,
  className = "",
  style,
  ...props
}: ScrollStoryProps) {
  const reduced = useReducedMotion();
  const rootRef = React.useRef<HTMLDivElement>(null);
  const listRef = React.useRef<HTMLDivElement>(null);
  const stickyRef = React.useRef<HTMLDivElement>(null);
  const trackRef = React.useRef<HTMLSpanElement>(null);
  const fillRef = React.useRef<HTMLSpanElement>(null);
  const stepRefs = React.useRef<(HTMLDivElement | null)[]>([]);
  const dotRefs = React.useRef<(HTMLSpanElement | null)[]>([]);
  const scroller = React.useRef<HTMLElement | null>(null);
  const [active, setActive] = React.useState(0);
  const [viewport, setViewport] = React.useState(0);
  const activeRef = React.useRef(0);
  const changed = React.useRef(onStepChange);
  React.useLayoutEffect(() => {
    changed.current = onStepChange;
  });

  // Where the reading line is: the middle of the view, or the middle of what the sticky picture leaves.
  const line = () => {
    const box = scroller.current?.getBoundingClientRect();
    const top = box ? box.top : 0;
    const height = scroller.current
      ? scroller.current.clientHeight
      : window.innerHeight;
    const wide = (rootRef.current?.clientWidth ?? 0) >= WIDE;
    const stuck = wide ? 0 : (stickyRef.current?.offsetHeight ?? 0);
    return top + stuck + (height - stuck) * (wide ? 0.5 : 0.42);
  };

  // On scroll: the rail fills to the line (written straight to the DOM), and the step at the line becomes active.
  const update = React.useCallback(() => {
    const list = listRef.current;
    const first = dotRefs.current[0];
    const last = dotRefs.current[steps.length - 1];
    if (!list || !first || !last) return;
    const y = line();
    const origin = list.getBoundingClientRect().top;
    const a =
      first.getBoundingClientRect().top + first.offsetHeight / 2 - origin;
    const b = last.getBoundingClientRect().top + last.offsetHeight / 2 - origin;
    if (trackRef.current)
      Object.assign(trackRef.current.style, {
        top: `${a}px`,
        height: `${b - a}px`,
      });
    if (fillRef.current)
      Object.assign(fillRef.current.style, {
        top: `${a}px`,
        height: `${Math.min(b - a, Math.max(0, y - origin - a))}px`,
      });
    let next = 0;
    stepRefs.current.forEach((el, i) => {
      if (el && el.getBoundingClientRect().top <= y) next = i;
    });
    if (next !== activeRef.current) {
      activeRef.current = next;
      setActive(next);
      changed.current?.(next);
    }
  }, [steps.length]);

  React.useLayoutEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    scroller.current = scrollParent(root);
    const target: HTMLElement | Window = scroller.current ?? window;
    let frame = 0;
    const onScroll = () => {
      if (frame) return;
      frame = requestAnimationFrame(() => {
        frame = 0;
        update();
      });
    };
    const measure = () => {
      setViewport(
        scroller.current ? scroller.current.clientHeight : window.innerHeight,
      );
      onScroll();
    };
    measure();
    target.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", measure);
    const observer = new ResizeObserver(measure);
    observer.observe(root);
    if (scroller.current) observer.observe(scroller.current);
    return () => {
      cancelAnimationFrame(frame);
      target.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", measure);
      observer.disconnect();
    };
  }, [update]);

  const jump = (i: number) => {
    const el = stepRefs.current[i];
    if (!el) return;
    const delta = el.getBoundingClientRect().top - line() + 2;
    const behavior: ScrollBehavior = reduced ? "auto" : "smooth";
    if (scroller.current) scroller.current.scrollBy({ top: delta, behavior });
    else window.scrollBy({ top: delta, behavior });
  };

  const pad = (n: number) => String(n).padStart(2, "0");

  return (
    <div
      ref={rootRef}
      className={`@container ${className}`}
      style={{ ...style, ["--story-h" as string]: `${viewport || 600}px` }}
      {...props}
    >
      <div className="grid @min-[520px]:grid-cols-2 @min-[520px]:gap-10">
        {/* The picture: beside the steps when there's room, stuck to the top when there isn't. */}
        <div
          ref={stickyRef}
          className={`sticky top-0 z-10 -mx-2 flex h-[calc(var(--story-h)*0.46)] flex-col items-center justify-center gap-3 border-b border-border bg-background px-2 @min-[520px]:mx-0 @min-[520px]:h-[var(--story-h)] @min-[520px]:border-b-0 @min-[520px]:bg-transparent @min-[520px]:px-0 ${
            side === "end" ? "@min-[520px]:order-last" : ""
          }`}
        >
          <p
            className="text-[11.5px] tabular-nums text-muted-foreground"
            aria-hidden="true"
          >
            <NumberRoll
              value={active + 1}
              format={{ minimumIntegerDigits: 2 }}
              duration={500}
            />{" "}
            / {pad(steps.length)}
          </p>
          <Stage index={active} reduced={reduced}>
            {steps[active]?.visual}
          </Stage>
        </div>

        <div
          ref={listRef}
          className="relative pb-[calc(var(--story-h)*0.12)] pt-8 @min-[520px]:pt-[calc(var(--story-h)*0.38)]"
        >
          <span
            ref={trackRef}
            aria-hidden="true"
            className="absolute left-[5px] w-px bg-border"
          />
          <span
            ref={fillRef}
            aria-hidden="true"
            className="absolute left-[5px] w-px bg-foreground"
          />
          {steps.map((s, i) => {
            const on = i === active;
            const reached = i <= active;
            return (
              <div
                key={i}
                ref={(el) => {
                  stepRefs.current[i] = el;
                }}
                aria-current={on ? "step" : undefined}
                className="relative min-h-[calc(var(--story-h)*0.42)] pl-7 @min-[520px]:min-h-[calc(var(--story-h)*0.55)]"
              >
                <span
                  ref={(el) => {
                    dotRefs.current[i] = el;
                  }}
                  aria-hidden="true"
                  className="absolute left-0 top-[3px] size-[11px] rounded-full border"
                  style={{
                    borderColor: reached
                      ? "var(--foreground)"
                      : "var(--border)",
                    backgroundColor: reached
                      ? "var(--foreground)"
                      : "var(--background)",
                    transform: on ? "scale(1.15)" : "scale(1)",
                    transition: reduced
                      ? "none"
                      : `background-color 240ms ${EASE}, border-color 240ms ${EASE}, transform 320ms cubic-bezier(0.34,1.36,0.64,1)`,
                  }}
                />
                <div
                  style={{
                    opacity: on ? 1 : 0.35,
                    transition: reduced ? "none" : `opacity 400ms ${EASE}`,
                  }}
                >
                  <p className="text-[11.5px] leading-4 tabular-nums text-muted-foreground">
                    {pad(i + 1)}
                  </p>
                  <h3 className="mt-1.5 text-[18px] font-semibold leading-tight tracking-tight text-foreground @min-[520px]:text-[20px]">
                    <button
                      type="button"
                      onClick={() => jump(i)}
                      className="cursor-pointer rounded-[4px] text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40"
                    >
                      {s.title}
                    </button>
                  </h3>
                  {s.body && (
                    <div className="mt-2 max-w-[36ch] text-[13.5px] leading-relaxed text-muted-foreground">
                      {s.body}
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

